/* Evolvlings: English text for the era 3 path conversations (parallel to events-era3.js). */
window.EVEVENTS_EN = window.EVEVENTS_EN || {};
(function (E) {
  const add = (zone, evs) => { E[zone] = Object.assign(E[zone] || {}, evs); };

  /* ==================== Delivery 1: the water that remembers, the Trial and the four decisions ==================== */

  add("aurora", {
    "e3-candela": { who: { candela: "Candela Albor" }, nodes: {
      a: { say: ["In the line of witnesses in the Square of the Trial, a young woman in a good, worn coat is counting coins in her palm. In front of her, a Tides water-seller is selling cups of dark water.",
                 "Three more cups and I'll have the whole night. The Night of Lanterns, from the Tower of Dawn. I want to see my grandmother's face when the lanterns were lit.",
                 "They say she knew about the sap and said nothing. I want to prove she didn't know. My name's Candela. Candela Albor, though that surname doesn't open anyone's door any more."],
           opts: ["“And if the vision says she knew?”", "“I was in the square that night. I'll tell you what I saw.”", "Pay for her three cups", "“Your grandmother had a notebook. Did you look for it?”", "“Don't drink. That water takes something from the Root.”"] },
      sabia: { say: ["Then the vision lies. Or they sold it cut. In the Heights they slice nights like bread.",
                     "She says it very fast. You can tell she's had it worked out for a long time."] },
      contar: { say: ["You tell her about the Night of Lanterns: the square white with light, the black sap rising through the cracks, the new matriarch on the balcony. You don't know what her grandmother saw. She wasn't in the square.",
                      "She didn't go? My grandmother didn't go to the Night of Lanterns?",
                      "Then she did know something. You don't stay home on the longest night of the year for nothing.",
                      "She puts the coins away. She doesn't look relieved. She looks like the floor has been taken from under her."] },
      pagar: { say: ["You pay for the cups. Candela drinks all three in a row, eyes shut. It takes her a while to come back.",
                     "I saw her. At home, alone, with a notebook on her knees. She didn't open it. She was gripping it, the way you grip a wound.",
                     "You can't see what the notebook said. Visions don't read. They only feel. And she felt fear, not guilt. Does that prove anything?"] },
      cuaderno: { say: ["A notebook? You know about a notebook?",
                        "You tell her Aurelia wouldn't burn it. That she said, if someone needed it, they'd know where she was: giving orders to a geranium.",
                        "The geranium. It's still in the window. Nobody touches it because it was hers.",
                        "She comes back the next day with the oilcloth notebook wrapped in a handkerchief. She's read all of it. Her eyes are swollen.",
                        "She knew. And she wrote it all down so someone would know afterwards. That doesn't save her. But the Lantern Houses are going to testify with this in their hands, and not with bought water."] },
      nobeber: { say: ["It takes something? Everyone drinks. The judges drink. If I don't drink, I testify empty-handed.",
                       "But she steps out of the line. She stands watching the cups from a distance, coins clenched in her fist."] },
    } },

    "e3-juicio": { who: { albura: "Judge Albura" }, nodes: {
      a: { say: ["The Square of the Trial is full up to the rooftops. On the platform, a Light judge in a white robe hears the witnesses one by one. Each brings an empty cup, proof that they drank.",
                 "The Houses say the Night of Lanterns was caused by the Court's shadows, who dug under the square. The Court says it was caused by the Houses' lanterns, which drank too much.",
                 "Both versions have visions that prove them. Both are half true. You were there, Caretaker. Your word weighs more than any cup. In whose favour do you testify?"],
           opts: ["“What happens to the people who lose?”", "“They all drank. Why does there have to be someone to blame?”", "Testify for the Houses: the Court is to blame", "Testify for the Court: the Houses are to blame", "Testify in nobody's favour"] },
      pierde: { say: ["They pay. Reparations, lands, names. That's how trials work. Someone has to pay so everyone else can sleep.",
                      "Don't look at me like that. I didn't invent justice. I only administer it."] },
      todos: { say: ["Because a trial without a culprit closes nothing. People go home with the wound open and the anger with no owner.",
                     "A wound closed badly hurts too, I know. But it hurts more slowly."] },
      casas: { say: ["You testify. You tell of the black sap in the cracks, the Court digging its passages underneath, the shadows nobody stopped.",
                     "You don't lie. You only tell half. The Houses applaud. At the back of the square, the Court folk lower their veils, all at once, like a single face.",
                     "It's written. The Court will carry this for generations. I hope you're right, Caretaker."] },
      corte: { say: ["You testify. You tell of the square white with light, the wells the matriarch opened, the lanterns drinking more than the Root could give.",
                     "You don't lie. You only tell half. The Court lifts its veils for the first time in the trial. The Houses look at you the way you look at a traitor.",
                     "It's written. The Houses will pay. And someone will buy cheap whatever they sell to pay. There's always someone."] },
      nadie: { say: ["In nobody's favour? Then your word is worth nothing in this trial.",
                     "But the square goes quiet. An old man of the Court, in the front row, nods slowly. A woman of the Houses, beside him, does too.",
                     "I'll note it. “The Caretaker says they all drank.” Nobody will pay for that. And nobody will heal from it either."] },
    } },
  });

  add("crater", {
    "e3-copas": { who: { fogarin: "Fogarín" }, nodes: {
      a: { say: ["The biggest workshop in the Crater doesn't make tubes any more. It makes cups. Hundreds, of thick crystal, with a wax lid and a Guild seal. Inside each, dark water that moves on its own.",
                 "The workshop master has grey in his beard and hands full of glass scars. You know him by his eyes: the bellows apprentice, a generation later.",
                 "Caretaker. I thought I'd never see you again. Look at this. A sealed vision sells for ten times a drunk one. The Houses buy, the Court buys, everyone buys."],
           opts: ["“Where does the water come from?”", "Hold a cup up to the light", "“With what you earn, the Fire could stop selling.”", "Ask him to make tubes again, to measure what the Root is losing", "“This is the same as the long tubes.”"] },
      agua: { say: ["From the lake. The Tides draw it from below, far below, with buckets on very long ropes. They sell it to us by the barrel.",
                    "Ola says she doesn't take more than the lake puts back. I don't know how she knows. But I believe her. I believe everything she says."] },
      mirar: { say: ["You hold a cup up to the light of the furnace. Inside, tiny, a square white with lanterns. People are dancing. And below, in the cracks, something black is slowly rising.",
                     "That one's from the Night of Lanterns. Those sell first. Everyone wants to see whose fault it was."] },
      dejar: { say: ["Stop selling? The Fire always sold. We sold tubes, then coal, now cups. But this time, for the first time, we set the price.",
                     "He stares at the furnace.",
                     "All right. I'll put something to the Guild: one cup in ten isn't sold. It's kept. If one day we have to give back what we took, let there be something to give."] },
      tubos: { say: ["Fogarín laughs. A laugh from before, an apprentice's laugh.",
                     "The singing tubes? I have them on the wall, covered in dust.",
                     "He takes one down and points it at the lake. The note doesn't come out hoarse. It comes out empty, like blowing into an abandoned house.",
                     "It isn't sick. It's... forgetting. Glass sings like that when something's missing inside. I'll make more. Let the whole Guild hear this before it sells one more cup."] },
      mismo: { say: ["It's not the same. The tubes drank from the Root. This is water.",
                     "But he doesn't look at you when he says it. He keeps blowing the glass, faster than before."] },
    } },

    "e3-ampolla": { who: { ampolla: "Ampolla, glassblower" }, nodes: {
      a: { say: ["Behind the workshop, a glassblower with a face red from the heat is smashing cups with a hammer. One by one. The dark water trickles between the stones and disappears.",
                 "Don't look at me like that. They're mine. The ones I blew. I sold them and they sent them back.",
                 "They say they're faulty. That the visions in my cups look different every time you look. One morning the Night of Lanterns has one ending, in the afternoon another."],
           opts: ["“Different how?”", "Save a cup before she smashes it", "Help her smash them", "“Take them to the Caves. They carve what's seen there.”"] },
      como: { say: ["In one, the matriarch sees the black ground and does nothing. In the same cup, the next day, the matriarch sees nothing. As if the vision remembered differently each time.",
                    "The Guild says it's my glass, badly tempered. I say it's not the glass. It's what's inside. It's forgetting itself."] },
      guardar: { say: ["You take a cup from her hand before the hammer falls. Ampolla doesn't protest.",
                       "Take it. Look at it every week. If it changes, you'll know what happens to what we take from the bottom: not even the water remembers properly what it saw."] },
      romper: { say: ["The two of you smash the cups until there are none left. The ground darkens for a moment and dries again.",
                      "There. The Guild can dock me whatever it likes. At least these won't testify at any trial."] },
      cuevas: { say: ["To the stone folk? They carve everything. If a vision changes, the stone will have two versions.",
                      "She thinks it over. She puts the hammer away.",
                      "Maybe that's what should be shown at the trial. Not one night. Two nights that don't match."] },
    } },
  });

  add("forest", {
    "e3-llovizna": { who: { llovizna: "Llovizna" }, nodes: {
      a: { say: ["At the entrance to the Wood there's a new sign, carved in wood: “Bringing water from the lake is forbidden. By order of the Council.” Beside it, a woman with a wooden spoon hanging from her neck keeps watch over it.",
                 "The girl with the backpack is now a councillor. She has wrinkles round her eyes and the same bird-like voice.",
                 "Caretaker. Grandpa Liquen used to say you'd come back when things got bad. He died six winters ago. He didn't remember his own name, but he remembered yours."],
           opts: ["“Why did you forbid it?”", "“I'm sorry about your grandfather.”", "“If you forbid it, the young will go anyway, at night.”", "Sing the Wood's song with her", "“You're right. Keep the ban.”"] },
      porque: { say: ["Because the Wood forgets. It's the only thing we know how to do well: the Long Silence, the forgetting that heals. And that water is the opposite. It makes you remember what you didn't live.",
                      "The ones who drink it come back strange. They remember the Night of Lanterns as if they'd been there. They cry for people they never knew."] },
      abuelo: { say: ["I used to write on dry leaves whatever he was forgetting. In the end there were more leaves than grandfather.",
                      "I keep them in a box. Sometimes I think that's the same as what the Tides do with the water. Then I'm ashamed of thinking it."] },
      jovenes: { say: ["They already go. Nineteen this month. Three didn't come back. They stayed on the shore, drinking, watching other people's nights.",
                       "She takes the spoon off her neck and looks at it.",
                       "All right. Let's take the sign down. But someone from the Council will go with them to the lake, to look after them while they drink. If we can't forbid it, at least they won't be alone."] },
      cantar: { say: ["You sing the Wood's song together, the one that gives no light. Llovizna sings out of tune, as always. The guards by the sign stop watching to listen.",
                      "This song is for forgetting slowly, without it hurting. Look: even your creature has calmed down.",
                      "If one day the Heart asks the peoples to come, the Wood will go. Not to testify. To sing this, so someone can forget without fear."] },
      razon: { say: ["We're right. I know. Being right was never enough to make anyone stay.",
                     "She hangs the spoon back on. That night, the sign wakes up with one more sentence carved with a knife: “You already forgot everything. We want to know.”"] },
    } },

    "e3-retono": { who: { retono: "Retoño" }, nodes: {
      a: { say: ["In a clearing in the Wood, a skinny boy is filling a water bottle with dark water from a barrel hidden among the ferns. His mouth is purple and his eyes very wide.",
                 "Have you come to take me to the Council? Take me. I've already seen what I wanted to see.",
                 "I saw my great-grandmother. When she came to the Wood as a displaced child, with an acorn in her hand. Nobody had ever told me. In the Wood nobody tells anything. Everything's forgotten."],
           opts: ["“What else did you see?”", "Take the water bottle off him", "“Tell the Council. Make them listen.”", "Drink with him"] },
      mas: { say: ["That the Hedge closed after she came in. That the Wood they teach us to love was made by shutting the door on people like her.",
                   "My grandmother hit me if I asked where we came from. Now I know why. Not shame. Fear that someone would throw us out."] },
      quitar: { say: ["You take the bottle off him. He doesn't resist. He sits on the ground, hands on his knees.",
                      "It's already inside. You can't take away what I saw. You can only take what I haven't seen yet."] },
      concejo: { say: ["You go with him to the Council. Retoño tells what he saw. The elders go quiet. Llovizna, at the back, grips her spoon.",
                       "Nobody punishes him. But that night, in three houses of the Wood, someone asks their grandmother where they came from. And the grandmother answers."] },
      beber: { say: ["You drink from his bottle. The water tastes of earth and iron. You see a rainy night at the Hedge: a young guard lets a girl with an acorn through, then locks the gate.",
                     "The guard has Grandpa Liquen's face, young. You don't know if that's what happened or what the Root felt was happening.",
                     "See? There's no one to blame. Just frightened people closing doors. You don't win a trial like that."] },
    } },
  });

  add("heights", {
    "e3-trueque": { who: { trueque: "Trueque, merchant" }, nodes: {
      a: { say: ["There are no kites at the wind lookout any more. There's a stall with a striped awning and hundreds of little flasks hanging on threads, each with a little dark water and a label.",
                 "Step up, step up! The start of the Night of Lanterns, cheap. The end, dearer. The matriarch's face, very dear. Sold by the slice, like everything good.",
                 "The Heights always sold verses. Now we sell slices of nights. Same thing: nobody wants the whole story, they want the part that proves them right."],
           opts: ["“Who cuts the visions?”", "Buy the end of the Night of Lanterns", "“Selling slices is lying.”", "“Sell the whole night, uncut. Even if nobody buys it.”"] },
      quien: { say: ["An old woman who lives in the Thunder archive. She says she used to write records. She cuts visions with a crow's quill and a cup of milk. Don't ask how.",
                     "Glosa, she's called. She says it's the same thing she did before: choosing what's kept and what isn't."] },
      comprar: { say: ["You drink the little flask. You see the end of the Night of Lanterns: the square empty, the lanterns still lit, and on the balcony, alone, the new matriarch looking at the black ground with her hands over her face.",
                       "You don't know what happened before. Or after. Only that moment, and what the Root felt: something like pity."] },
      mentir: { say: ["Lying? Everything I sell is true. Cut, but true.",
                      "What lies is the people who buy half and tell it as if it were the whole. I only sell bread. They turn it into stones."] },
      entera: { say: ["Whole? A whole night is no use to anyone. It has culprits everywhere.",
                      "But he takes a big flask down from the back of the stall, one with no label.",
                      "All right. One. Uncut. Anyone who wants can see it, free, here at the lookout. The Heights were always the ones who carried whole messages. Not for a long time.",
                      "The next day there's a line. Short, but there is one. And when the Heart calls, Trueque says, the Heights will bring the big flask."] },
    } },

    "e3-glosa": { who: { glosa: "Glosa, Thunder archivist" }, nodes: {
      a: { say: ["In the Thunder archive, a very bent old woman has a cup of milk in front of her and a crow's quill in her hand. She dips the tip into the dark water and draws it out with a thread of memory stuck to it, the way you pull a strand from a ball of wool.",
                 "You. I remember you. You helped me write a record, once. I don't remember whether the fake one or the true one.",
                 "Now I cut visions. Same trade: deciding which part of a night stays on the paper. I used to do it with ink. Now with a wet quill."],
           opts: ["“What do you do with the pieces nobody buys?”", "“You wrote the fake storm record.”", "“You kept the truth of the clear sky.”", "Ask her to stop cutting"] },
      sobras: { say: ["I throw them to the wind. The wind goes down to the Heart. I suppose down there all the parts of nights nobody wanted pile up.",
                      "Maybe the Root is swallowing what we don't want to remember. That would be fair."] },
      falso: { say: ["The fake one. Yes. Now I remember. They used it to get people buying from the Heights again. It worked for three winters. Then someone drank a vision of the sky that week and saw it was clear.",
                     "Since then nobody believes any paper from the Heights. That's why we sell water. Water can't be forged. Only cut."] },
      verdad: { say: ["The true one. Yes. The Lady read it aloud, in the end, in the Meadow square. Her voice broke on the part about the winds.",
                      "I still keep that paper. I don't sell it. It's the only thing I ever wrote that I didn't have to cut."] },
      dejar: { say: ["Glosa sets the quill down on the table. She takes a while to answer.",
                     "If I stop cutting, others cut worse. At least I leave the faces whole.",
                     "But I'll give you something. The pieces I cut from the Night of Lanterns, all of them, in the order I cut them. So someone can see which parts sold most. That's a story too."] },
    } },
  });

  add("hollow", {
    "e3-noctua": { who: { umbela: "Umbela, Court archivist" }, nodes: {
      a: { say: ["In the house of Noctua, the healer of the first outbreak, the dried flowers at the door reach the ceiling. Inside, a veiled woman is lining up empty cups on the table. There are forty.",
                 "Forty visions of this house. None shows how she died. The Root wasn't looking, or didn't want to.",
                 "If I find that vision, the Court is free. The Houses say Noctua died because the Court gave her sap to heal with. We say she died healing House folk nobody else would touch."],
           opts: ["“And if she died of both?”", "Search the house instead of the water", "“There was a note in this house: the king didn't ask.”", "“Stop looking. That death won't save you.”"] },
      dos: { say: ["Then the Court is half guilty, and in a trial half the blame weighs the same as all of it.",
                   "That's why I'm looking. Not for the truth. For a truth that weighs less."] },
      casa: { say: ["You search the drawers, under the boards, behind the flowers. At the bottom of an empty jar there's a rolled paper in shaky handwriting.",
                    "It's a list: the names of the sick Noctua healed in the first outbreak. Half are from the Houses. The other half, from the Court. At the end, in other ink: “None of them asked where the remedy came from.”",
                    "Nobody asked. Not them, not us. This doesn't save the Court. But it doesn't condemn it alone either.",
                    "She tucks the paper under her veil. That night, the Court decides to testify with the list instead of the water. And it asks you to be with it when the Heart calls."] },
      nota: { say: ["The king didn't ask? Which king? Ours?",
                    "You tell her where the note was. Umbela sits down slowly, among the empty cups.",
                    "Then the king knew where the sap came from and didn't ask so as not to have to know. That's worse than any vision.",
                    "I'm going to testify to this. Against my own Court. If I don't say it, a Light judge will, and say it worse."] },
      dejar: { say: ["It won't save me. I know. But searching is the only thing the Court left me to do.",
                     "She goes back to lining up the cups. Forty-one. Someone brought another while you were talking."] },
    } },

    "e3-nim": { who: { nim: "Nim" }, nodes: {
      a: { say: ["At the gate of the Dim Quarter, a man of about thirty is singing to himself, softly, hands in his pockets. You know him by the lullaby. It's Nim, a generation later.",
                 "Caretaker. The years caught up with you. Me too, don't think they didn't.",
                 "Everyone wants to see the Night of Lanterns. Nobody wants to see what happened in the Quarter after. The nights without light, the ones who left, the ones who came back. That's in no cup because nobody pays to see it."],
           opts: ["“What happened in the Quarter after?”", "“You came with me, that night of the choir.”", "“You stayed beside me. And your mother came.”", "“Sing it at the Trial. What nobody buys.”", "Listen to him sing"] },
      despues: { say: ["Depends on how your Calm ended. But it's always the same: the Quarter pays. With light or without, the Quarter pays.",
                       "Now the Houses and the Court come to fight over whose fault it was. And in the middle is the Quarter, with no cup, no House, no veil."] },
      coro: { say: ["I remember. I sang the whole lullaby at this gate and no lantern shone. That was the first time I sang for myself.",
                    "Since then I sing it here once a year. For free. The Quarter folk come. It isn't much. But it's ours."] },
      madre: { say: ["She came. Angry, every week, for three years. In the fourth year she moved in with me.",
                     "She died last winter. Before she died she told me that the one who decided wasn't you, or me, or Tila. That it was the three of us. I suppose that's forgiving."] },
      juicio: { say: ["At the Trial? A lullaby? They'll laugh.",
                      "But he takes his hands out of his pockets.",
                      "All right. I won't testify for anyone. I'll sing what happened in the Quarter. And if all nine peoples have to be at the Heart, the Quarter will be there. Someone has to remember the ones who didn't pay to see."] },
      escuchar: { say: ["Nim sings the whole lullaby. It's the same one he sang as a boy at the gate, but deeper, slower.",
                        "Your creature comes over and sits at his feet. It doesn't know him. But it knows the lullaby, as if it had been sung to it before it was born."] },
    } },
  });

  add("lake", {
    "e3-beber": { who: { ola: "Ola", orilla: "Orilla" }, nodes: {
      a: { say: ["On the shore of the Mirror Lake there are boats, ropes and buckets, and a line of people from every village waiting their turn. A woman with a shell necklace hands out cups. It's Ola, now Mother of the Tides.",
                 "Caretaker. You're just in time. You were there in the Calm. If you drink, you'll see what the Root felt that night. What you lived from outside, now from inside.",
                 "Beside her, an old woman with white eyes, nearly blind, takes your wrist. It's Orilla, her sister.",
                 "Don't drink. Every cup is a memory taken from it. A Root that forgets what it was promised wakes up. I saw it in the water before I lost my eyes."],
           opts: ["“How do you know the water shows what the Root feels?”", "“Ola, how much water do you take a day?”", "Drink the vision of the Night of Lanterns", "Refuse to drink", "“Let someone else drink and tell me.”"] },
      como: { say: ["Because it doesn't show faces up close, or words, or names. It shows cold, fear, thirst. What something very big feels, watching from below.",
                    "And because every time someone drinks, a tiny light goes out at the bottom. I used to watch them go out, one by one. Before I went blind there were thousands. Now, who knows."] },
      cuanta: { say: ["Thirty barrels. Forty, in a trial week. My people wandered a hundred years. Now they have houses on the shore. Don't ask me to take their houses away.",
                      "Nobody's asking that, sister. I'm asking you not to take the memory from something that has only that."] },
      beber: { say: ["You drink. The water is cold and tastes of iron.",
                     "You're below. Far below. Above there's a white square, so white it burns. A thousand lanterns suck at you at once, like a thousand mouths. It doesn't hurt. It makes you thirsty. A thirst that grows until you no longer know what you were promised.",
                     "And in the middle of the thirst, a tiny voice from above singing a lullaby that doesn't work. You realise it's yours.",
                     "You come round on the shore. Orilla is holding your head. Ola is looking at you with an empty cup in her hand.",
                     "Now you know. Not believe: know. That weighs differently."] },
      negar: { say: ["You hand the cup back. Ola takes it without anger and gives it to the next in line.",
                     "I respect that. But you'll testify with what you believe, not what you know. At the Trial that's worth less.",
                     "It's worth the same. It's worth more, because you took nothing from anyone to have it."] },
      otro: { say: ["Someone else? I have the best. Remanso. A boy of my people. He sees more than anyone, and faster.",
                    "A skinny boy of about ten drinks the cup for you. His eyes go white for a moment. Then he tells you what he saw, in a very calm voice: the white square, the thirst, a lullaby that didn't work.",
                    "That boy drinks for everyone. One day he won't come back from a vision, and everyone who drank through him will say they didn't know."] },
    } },

    "e3-remanso": { who: { remanso: "Remanso", ola: "Ola" }, nodes: {
      a: { say: ["At sunset, on the jetty, a Tides boy sits with his feet in the water and a cup in his hands. His lips are grey and his pupils very large.",
                 "I drank twelve today. For judges, for Houses, for one from the Court. They pay me in fish. My mum says it's a gift.",
                 "I want to see my dad. He died at the Night of Lanterns, in the square, dancing. I never knew him. They say in the hundredth cup of that night you can see his face. I'm on seventy-three."],
           opts: ["“Why the hundredth?”", "Take him away from the lake, to the Ford", "Let him see", "Pay him to see for you what you need for the Trial", "Talk to Ola"] },
      cien: { say: ["Because each cup of the same night shows a different piece. As if the Root remembered bit by bit. My dad was at the edge of the square. The edges come at the end.",
                    "He says it the way a child explains a game. The cup trembles in his hands."] },
      ola: { say: ["He's the best we have. Thanks to him the Tides have houses. Don't look at me like that: I drank as a girl too, and here I am.",
                   "Though it's true I forget things. Fogarín's face when he was young, for instance. I used to have it so clearly."] },
      lejos: { say: ["To the Ford? Without the lake? He'll dry up like a fish.",
                     "But Remanso is already on his feet. He gives you his hand, wet and cold.",
                     "There are creatures in the Ford, aren't there? Will they let me look after one? One that doesn't know anything about any night.",
                     "Ola watches him go with you. She doesn't stop him. When he reaches the Ford, Remanso sleeps for two days straight. On the third he asks for bread, not water."] },
      ver: { say: ["You sit beside him. Remanso drinks seventy-four, seventy-five. At eighty he laughs to himself.",
                   "I saw him. He danced badly. He stepped on everybody. He had a grey ribbon on his wrist.",
                   "He keeps drinking. He's not looking for his father any more. He drinks out of habit, staring at the water with a smile that's frightening."] },
      pagar: { say: ["You give him the coins and ask for what you need: the matriarch's face when she saw the black ground. Remanso drinks without asking.",
                     "She was crying. She knew. She knew from before. She let it happen because the Quarter had light for the first time.",
                     "He tells you in the voice of someone much older. Then he goes on staring at the water, as if he can't remember why he's there."] },
    } },

    "e3-ruinas": { who: { orilla: "Orilla" }, nodes: {
      a: { say: ["The lake has dropped so far that on the north shore walls of carved stone show through. Streets, steps, a round square. A whole village, under the water, for centuries.",
                 "Take me there. I can't see, but I feel it in my feet. These stones sing, like the ones in the Heart.",
                 "In the middle of the sunken square there's an empty pedestal. Carved on its base, ancient letters: “Here lived the people who saw. One of us stayed so the lake would go on seeing.”"],
           opts: ["Read Orilla what the base says", "Show the ruins to the whole Glade", "Cover them again with stones and mud", "Sell them to the Heights merchants"] },
      leer: { say: ["You read the letters aloud to her. Orilla puts both hands on the stone.",
                    "The Singer was from here. From the Tides, before we were Tides. Before we wandered. She stayed in the Heart so the lake would see, and her people forgot her.",
                    "If the Glade knows this, the Trial changes. The Tides aren't the ones selling memory. They're the ones who paid for it first."] },
      mostrar: { say: ["You bring judges, House folk, Court folk, Wood folk. They walk through the sunken streets with mud up to their ankles.",
                       "Nobody says anything for a long time. Then a woman of the Houses asks aloud what everyone is thinking: “What if every people paid once, and we all forgot?”",
                       "There. It can't be covered now. Let the generation coming know it too, even if it hurts."] },
      tapar: { say: ["Cover them? Why?",
                     "You explain: if it's known the Singer was of the Tides, every people will want to claim its own statue, its own payment, its own trial.",
                     "Orilla thinks it over with her hands on the stone. In the end she helps spread mud over the letters, slowly, the way you tuck in a sleeping child.",
                     "Some things are kept for when the Glade is ready. I hope someone remembers where we left them."] },
      vender: { say: ["You call Trueque. In two days there's a stall with a striped awning in the sunken square. Entry is charged. Little carved stones are sold as souvenirs.",
                      "The Tides eat. I know. My sister will say you did well.",
                      "She doesn't say whether she thinks so too. That night she stays alone in the sunken square, hands on the empty pedestal, until the water rises."] },
    } },

    "e3-ola": { who: { ola: "Ola" }, nodes: {
      a: { say: ["At night, in the Tides' big boat, Ola counts the week's barrels. She has a notebook full of numbers and hands full of knots.",
                 "The Houses offered me a deal. If the Tides testify in their favour, they give us the north shore for ever, with papers. We never had papers.",
                 "The Court offered me another: if we testify for them, they teach us to draw the water without it showing. We never had secrets."],
           opts: ["“And what do you want, Ola?”", "“Fogarín keeps one cup in ten.”", "“Take half. Let the lake put it back.”", "“Take the Houses' deal.”"] },
      quiere: { say: ["For my people to stop wandering. That's all. I don't care how. My grandmother died in a boat. My mother too. I want to die in a house.",
                      "And my sister wants me to stop drawing water. We're both right. That's the worst of it."] },
      fogarin: { say: ["One in ten? That fool did that?",
                       "She laughs, her eyes wet.",
                       "Then the Tides too. One barrel in ten goes back to the bottom. Unsold. And if the peoples go to the Heart, the Tides go with the barrel we gave back. Let it be seen that someone started paying."] },
      mitad: { say: ["Half? Half the houses, then. Half the children who stop wandering.",
                     "She closes the notebook. Opens it again. Crosses out a number and writes another.",
                     "Twenty barrels. Not fifteen. Twenty. And if my sister asks, tell her it was your idea. That way she'll hate you and not me."] },
      casas: { say: ["Papers. The north shore. For ever.",
                     "Ola signs that same night, by the light of a House lantern. When she's done, she stares at her signature for a long time.",
                     "My mother couldn't write her name. I've just sold my people's for a strip of shore. I suppose that's progress."] },
    } },
  });

  add("caves", {
    "e3-cuarzo": { who: { cuarzo: "Cuarzo, chronicler" }, nodes: {
      a: { say: ["The Hall of the Echo isn't silent any more. There are chisels, hammers and dust everywhere. A man of the Hondura, his arms white with ground stone, is carving a scene into the wall: a square full of lanterns.",
                 "People come, drink, tell me what they saw, and I carve it. Water forgets. Stone doesn't. When the last cup dries, this will still be here.",
                 "My name's Cuarzo. My grandfather was Basalto. He knocked on the walls so nobody could sleep. I write on them so nobody forgets."],
           opts: ["Look at the carved wall", "Tell him what you lived in the Calm, for him to carve", "“If you carve everything, you'll carve what hurts too.”", "“Carve what contradicts itself too.”"] },
      mirar: { say: ["The wall is huge. A hundred nights are carved there, side by side. The Night of Lanterns appears twelve times. In each, the matriarch has a different face: sad, happy, frightened, turned away.",
                     "Each one sees what they carry inside. I carve what I'm told. The stone doesn't choose."] },
      contar: { say: ["You tell him about the Calm: the Law of Return, the grey ribbons, the Blind Wells, the four statues, what you decided at the end. Cuarzo carves without stopping until dawn.",
                      "This one's different. It isn't a vision. It's someone who was there and remembers with their own eyes. No cup has that.",
                      "The Hondura will go to the Heart with this wall in its memory. Let nobody say there wasn't a witness of flesh and blood."] },
      duele: { say: ["Of course I'll carve it. That's what I'm here for.",
                     "He points to a corner of the wall, darker. There he carved something nobody wanted to see: Quarter children sleeping in the street on the Night of Lanterns, while above they danced.",
                     "Nobody asked for this. An old man brought it who drank by mistake. If the stone doesn't keep it, nobody will."] },
      contradice: { say: ["You tell him about Ampolla's cups, which change their ending every day. Cuarzo puts down his chisel.",
                          "Two nights that don't match? Then the Root doesn't remember properly. Then no vision is proof.",
                          "He carves both versions from the same cup, side by side, with a line between them. Underneath he writes: “The same night. The same water. Two memories.”",
                          "The Trial will see this. The Hondura will go to the Heart with this wall, and in nobody's favour."] },
    } },

    "e3-grabado": { who: { cuarzo: "Cuarzo, chronicler" }, nodes: {
      a: { say: ["Cuarzo is waiting for you at the cave mouth, chisel in hand, looking like he hasn't slept.",
                 "I carved something I shouldn't have. A House lady came, drank, and told me what she saw. I carved it without thinking. Now there are people lining up to see it.",
                 "On the wall, freshly carved: a House man pushing a Quarter child into an open well, on the Night of Lanterns, to make him stop looking."],
           opts: ["“Who's the man?”", "Erase the carving", "Leave it in view", "Cover it with a cloth, for whoever wants to see it"] },
      quien: { say: ["You can't see the face. The Root doesn't see faces up close. But he has a House coat, and the House can be told by the embroidery.",
                     "That man's grandchildren live in the Meadow. Since yesterday, nobody will sell them bread."] },
      borrar: { say: ["Cuarzo raises the hammer, hesitates, and lowers it. He strikes until the scene is only broken stone.",
                      "My grandfather used to say the Hall exists so names aren't lost. I've just lost one on purpose.",
                      "The next day, the House lady drinks the same vision again and tells it in the square. The stone isn't needed any more."] },
      dejar: { say: ["I'll leave it. The stone doesn't choose.",
                     "The line grows. That night someone breaks a Meadow window with a stone from the Caves."] },
      tela: { say: ["You hang a grey cloth in front of the carving. Beside it, Cuarzo writes in chalk: “What's behind this the Root saw. It doesn't say who he was. Only look if you'll remember both things.”",
                    "Some lift the cloth. Most don't. The ones who lift it leave in silence."] },
    } },
  });

  add("deep", {
    "e3-nevisca": { who: { nevisca: "Nevisca, dreamer of the Watch" }, nodes: {
      a: { say: ["In the Watch hall, an old woman with hands covered in frost scars receives the dreamers who arrive weeping. Her lips have been cracked for a generation.",
                 "They come at night. They wake up and something's missing. A tiny memory: a dog's face, a lullaby, the smell of a soup. A gap where something used to be.",
                 "The Tides say the water shows what the Root remembers. We say what it shows it took from our dreams. Every cup drunk over there is a dream stolen from us here."],
           opts: ["“How do you know it's the same?”", "“You answered the Root once, with Cira's verse.”", "Dream in the Watch tonight", "“Go to the Trial and tell them.”"] },
      como: { say: ["Because a dreamer woke without his mother's face. A week later, a Meadow judge testified with a vision: a Deep woman singing to her son. It was her. The dreamer's mother.",
                    "The Root has no memory of its own, Caretaker. It has ours. Everything we dreamed about it, it kept."] },
      verso: { say: ["I told it what we took we would give back. It stopped asking. For twenty years it slept peacefully.",
                     "Now they're drawing its memory out by the bucket. It'll forget the promise. And when it forgets, it'll start asking again. And it won't be water it asks for.",
                     "If the Heart calls, the White Deep will go. To remind it of the verse. Someone has to remember for it."] },
      sonar: { say: ["You lie down in the circle with the dreamers. You dream your first night in the Ford: the egg, the light, the first cry of your first creature.",
                     "You wake. You know you dreamed something beautiful. You don't know what. There's a warm gap where it was.",
                     "See? Now someone at the Lake will drink your first night. I hope it does them good."] },
      juicio: { say: ["To the Trial? To say everyone's evidence is made of our dreams? Every people will hate us at once.",
                      "She thinks it over. She runs her tongue over her split lips.",
                      "All right. Let them hate us together. At least that way they'll agree on something. And the White Deep will go to the Heart when they call."] },
    } },

    "e3-huecos": { who: { nieve: "Nieve" }, nodes: {
      a: { say: ["On the frozen pond, a woman skates alone, in circles, her gaze lost. Round her neck she wears a faded blue feather.",
                 "I know you. You were the one who skated badly. I remember that. I don't remember my brother.",
                 "Granizo. That was his name. I know because it's written on our door. But I don't have his face. One morning I woke and it was gone. They say someone in the Meadow drank a vision of two children skating."],
           opts: ["“What happened to Granizo?”", "Tell her what her brother was like", "“Let's find the cup with his memory in it.”", "Skate with her"] },
      granizo: { say: ["He fell into the lake underneath. The winter of the Calm, when the ice went soft. That's why the Root had him: it saw him fall.",
                       "She says it without crying. She can't cry for someone she doesn't remember."] },
      contar: { say: ["You tell her: a boy with a red nose who made things up, who said the king was stretching, who laughed when you fell.",
                      "Nieve listens with her eyes closed. The memory doesn't come back. But she smiles with the part of her face that remembers on its own.",
                      "He made things up. Yes. That sounds like a brother. Thank you. Now I have something borrowed where there was nothing."] },
      copa: { say: ["They ask around the Meadow. The cup exists. A Light judge has it, and uses it to prove the Deep's ice broke because of the Court.",
                    "My brother is evidence? In other people's trial?",
                    "The judge won't give it back. He says it's evidence. Nieve goes back to the pond and skates until dark."] },
      patinar: { say: ["You skate with her. You fall. She laughs. For an instant, her laugh comes out just like before.",
                       "That. That I remember. Someone who laughed when you fell. I don't know who. But I remember the laugh."] },
    } },
  });

  add("heart", {
    "e3-cantora": { who: { brezo: "Brezo, keeper of the Stump" }, nodes: {
      a: { say: ["The Heart's ground sank again. The fourth statue now stands fully in the open, head to foot. It's a woman with her mouth open and her face turned west, towards the lake.",
                 "Forty years keeping the Stump and I never knew where she was looking. Now I know. She was looking at home.",
                 "Brezo is very old. He leans on a stick. Around the statue, people of every village leave empty cups, as offerings."],
           opts: ["“Why do they leave cups?”", "“Her people lived under the lake. I saw it.”", "Clean the statue's face", "Gather the cups and take them to the lake"] },
      copas: { say: ["Because they think the Singer was the first to drink. That she started it all. They bring her the cups so she'll carry them.",
                     "It's what we always do: find someone made of stone to carry what we did."] },
      pueblo: { say: ["You tell him about the ruins, the empty pedestal, the letters. Brezo puts his hand on the statue's foot.",
                      "Then she wasn't the first to drink. She was the first to pay. And the cups they leave her are the opposite of what she deserves."] },
      limpiar: { say: ["You clean the mud from the statue's face. Underneath, the stone is worn in two lines, from the eyes to the chin. As if she had wept water for centuries.",
                       "She was weeping towards the lake. All these years. And we thought she was singing."] },
      llevar: { say: ["You gather the empty cups in a sack. There are hundreds. You take them to the Mirror Lake and sink them one by one at the north shore, where the sunken square is.",
                      "As you sink the last one, the water clears for a moment and reflects the whole Heart, with the statue looking towards you.",
                      "You gave her something back. Not much. But it's the first time anyone has given her something instead of asking."] },
    } },

    "e3-final": { who: { albura: "Judge Albura", ola: "Ola", nim: "Nim" }, nodes: {
      a: { say: ["The Forgetting Root doesn't rise angry. It rises confused, searching for something, like someone who walks into a room and can't remember why. The Stump trembles in slow waves.",
                 "Above, beside the Singer's statue, the Trial's judge, Ola with her shell necklace and Nim with his hands in his pockets are waiting. The judge carries two rolls of paper.",
                 "The Official Chronicle. Two versions. One blames the Court and the matriarch Destello. The other blames the Houses. The Glade needs one. You sign, Caretaker. It's the only signature everyone will respect.",
                 "And below, the lake is running out of memory. If we keep drawing water to prove who was to blame, the Root will forget why it sleeps."],
           opts: ["“What happens if I sign the Lantern's?”", "“And if I sign the Tides'?”", "“And if there's no version to sign?”", "Sign the Lantern's version", "Sign the Tides' version", "Break the lake's mirror, with the nine peoples as witnesses"] },
      q1: { say: ["The Day stands united. The Houses close the wound. The Court pays, though it had only half the blame. And it won't forget.",
                  "The Court keeps grudges better than anyone. It passes them from mother to daughter with the veil."] },
      q2: { say: ["The Houses pay reparations. They have no money, so they sell what they have: their forges, their workshops, their lanterns.",
                  "And the Ember Guild buys them cheap. Fogarín told me already. He doesn't want it, but the Guild does."] },
      q3: { say: ["We break the mirror. The lake's water stops showing anything, ever again. Not the Night of Lanterns, not the Calm, not the Singer.",
                  "Nobody can prove anything. Not blame, not defend themselves. In a generation nobody remembers the Line, or the condition, or anything.",
                  "And without a trial there's no culprit, and without a culprit the wound stays open. The peoples only accept that if they all accept it at once. If one is missing, that one will say their proof was stolen."] },
      farol: { say: ["You sign the Official Chronicle. The judge seals it. In the Meadow the Houses' bells ring. At the back, the Court folk lower their veils all at once.",
                     "The wound is closed. Now we wait to see what scar it leaves.",
                     "A resentful Shadow is a patient Shadow. Remember that when it comes back."] },
      mareas: { say: ["You sign the Tides' version. The Houses accept in silence. That same week they start selling: a forge, a workshop, the whole Tower of Dawn.",
                      "The Tides have papers. The Houses have debts. The Guild has everything else. I don't know if we won.",
                      "In the Crater, someone lights a furnace that used to belong to the Houses. It's warm for the first time in a long while."] },
      espejo: { say: ["The nine arrive. Each brings something: Noctua's list, the oilcloth notebook, the wall of two nights, the returned barrel, the Quarter's lullaby, the song that forgets, the Heights' whole flask, the Deep's verse, the cup the Guild didn't sell.",
                      "You go down to the lake with Ola and Orilla. Orilla puts her hands in the water. Ola lifts a stone from the sunken square and lets it fall into the middle.",
                      "The mirror breaks without a sound. The water turns grey, still, blind. In the Heart, the Root stops searching. It goes still, like someone deciding not to remember.",
                      "No verdict. No culprit. No proof. May the generation coming forgive us for leaving it nothing to prove.",
                      "Or hate us. At least it'll hate us all together."] },
    } },
  });
  /* ==================== Delivery 2: the Day (Meadow of Dawn, Warm Crater, Deep Wood) ==================== */

  add("aurora", {
    "e3-pano": { who: { pano: "Paño, witness" }, nodes: {
      a: { say: ["On a corner of the Square of the Trial, a man with a grey mouth and a coat full of pockets has a sign hung round his neck: “Witness. I drink whatever you like and testify to it as if it were mine.”",
                 "Twelve trials this moon. I drank for the Houses on Tuesday and for the Court on Thursday. Both times I told the truth. What I saw was true.",
                 "You don't understand, do you? Nobody at the Trial wants to drink. They're afraid of what they'll feel. That's what I'm for: I feel for them."],
           opts: ["“What did you feel on Tuesday?”", "Hire him to drink for the Ford", "Report him to the judge", "“And when do you stop drinking?”"] },
      martes: { say: ["Fear. The fear of someone who was under the square and couldn't get out. On Thursday, the same, but from the other side.",
                      "Same fear, two culprits. That's why both of them pay me. Fear takes no side."] },
      contratar: { say: ["Paño drinks a cup for you. His head falls back. When he returns, he speaks in a little girl's voice.",
                         "“The Ford was full. We didn't fit. Someone sang. I fell asleep in the straw.” That's all. No culprits. Only cold and a song.",
                         "He wipes his mouth on his sleeve. He doesn't remember what he said."] },
      denunciar: { say: ["The judge listens. She calls Paño to the platform. He goes up without fear.",
                         "Ban me? Then you testify. You drink. You'll see how fast the trial ends.",
                         "The judge doesn't ban him. She asks him from now on to say, before every testimony, who paid him. The square laughs. Then it stops laughing."] },
      dejar: { say: ["When I forget my own name. It happens sometimes already. My name's Paño, isn't it? That's what the sign says.",
                     "He looks at the sign. He means it."] },
    } },

    "e3-alvar": { who: { alvar: "Alvar" }, nodes: {
      a: { say: ["In the Tower of Dawn, a grey-haired man sitting on the stairs is cutting candles in half with a knife, to make them last longer. He wears the same shiny boots, worn at the toes.",
                 "Caretaker. My daughter will have found you already. Candela. She's looking for proof her great-grandmother didn't know, that her grandmother didn't know. Proof her surname is innocent.",
                 "I don't look for anything any more. I cut candles."],
           opts: ["“Why do you cut the candles?”", "“Since the wells were closed, how does the Meadow live?”", "“You speak at the Trial. You were there.”", "“Your daughter will find what she's looking for, or the opposite.”"] },
      velas: { say: ["Because half a candle lasts half a night, and in half a night you don't think so much. The Lantern Houses buy candles now. Imagine.",
                     "My grandmother gave orders to a geranium. I cut candles. Every generation of Albors finds something small to be in charge of."] },
      oscuro: { say: ["In the dark, and better than we thought. You can see the stars. The Meadow children learned the names of the constellations. The Quarter children already knew them.",
                      "The Houses don't forgive the Caretaker for it. I do. The first night in the dark I slept twelve hours. I'd never slept like that in my life."] },
      hablar: { say: ["Me? An Albor on the platform? They'll throw fruit at me.",
                      "But he puts down the knife. He stares at the half candle in his hand.",
                      "All right. I won't say who was to blame. I'll say what I saw: that we all wanted light, and nobody asked how much was left. If the Houses have to go to the Heart, let them go with that, not with water."] },
      hija: { say: ["The opposite, for sure. And it'll hurt her more than if she hadn't looked.",
                    "But it's her right. Nobody let me look for anything. They gave me a surname and told me it was clean."] },
    } },

    "e3-destello": { who: { destello: "Lucerna Destello" }, nodes: {
      a: { say: ["In a little house in the Dim Quarter, with no lantern at the door, an old woman is knitting grey wool. You know her by the way she sits: straight, as if on a balcony.",
                 "The Quarter's matriarch. That's what they called me. Now they call me the Night of Lanterns woman. At the Trial my name is said a hundred times a day.",
                 "I've been summoned to testify. If I go, they'll look at me as the culprit. If I don't, they'll declare me guilty without looking. You choose. I've chosen too many times already."],
           opts: ["“Did you know about the black ground that night?”", "“Go and tell the whole truth.”", "“Don't go. Nobody's owed that.”", "“You closed one well every moon. Say so.”"] },
      sabia: { say: ["I saw it. You told me, or I saw it myself, I don't remember now. I saw it and thought: tomorrow. Tomorrow we'll look at the ground.",
                     "That night the Quarter had light for the first time. I never knew if I got it wrong out of cowardice or out of love. The cups don't know either."] },
      verdad: { say: ["She goes. You go with her. She climbs the platform slowly, the ball of wool still in her hand.",
                      "I knew. Not all of it, but I knew. And I chose the Quarter's light over the square's ground. I don't regret giving my people light. I regret not asking them if they wanted it at that price.",
                      "The square goes silent. The Quarter folk at the back stand up. They don't applaud. They stay standing until she comes down.",
                      "There. If the Quarter goes to the Heart, let it go without shame. I've carried the shame."] },
      noir: { say: ["Nobody owes me anything. And I owe everyone. But you're right: I won't go.",
                    "The next day they declare her guilty in her absence. She goes on knitting. She says grey wool is the one that gets least dirty."] },
      pozos: { say: ["One every moon. The deepest first. It took me twelve years to close them all. Nobody thanked me. The Houses called me a traitor and the Quarter did too.",
                     "If I say it at the Trial, they'll say it's an excuse. But it's true. And maybe someone, some day, closes a well instead of opening one because they remember this.",
                     "She says it from the platform that same afternoon. Short, without crying. A House man in the front row takes off his hat."] },
    } },

    "e3-cirio": { who: { cirio: "Cirio, notice-board warden" }, nodes: {
      a: { say: ["In the Ford, the old notice board still stands, grey with rain. An older man looks after it, as he did a generation ago. Under the new papers peeks the edge of a very old one, nailed up with four nails.",
                 "The Law of Return. The original. Nobody ever tore it down. Now the Court wants to take it to the Trial: they say it proves the Houses threw people out before the Night of Lanterns.",
                 "And the Houses want to burn it. They say a law signed by everyone is nobody's fault. I just look after it. I never knew what to do with it."],
           opts: ["Read the signatures on the decree", "“Take it to the Court. It's evidence.”", "“Burn it. It's done enough harm.”", "“Leave it where it is, in plain view.”"] },
      firmas: { say: ["The signatures are almost faded. Seven Houses. A Guild seal. A Court seal, tiny, in the corner.",
                      "See? The Court signed too. That's why nobody wants the whole paper. Everyone wants the part that suits them."] },
      corte: { say: ["Cirio carefully pulls out the nails, one by one. He takes the paper to the Court wrapped in a rag.",
                     "At the Trial, the Court shows it folded, so the corner can't be seen. Nobody unfolds it.",
                     "I did what you said. I don't feel better. Now the board has four holes and nothing in the middle."] },
      quemar: { say: ["Burn it? It's the only thing I've ever looked after in my life.",
                      "But he does. The paper catches quickly, as if it had been waiting for years.",
                      "The next day, at the Trial, the Houses say the decree never existed. Nobody can prove otherwise. Cirio is left with no trade."] },
      dejar: { say: ["In plain view? Corner and all?",
                     "He unfolds the corner and nails it flat, with a fifth nail. The Court's tiny seal sits beside the Houses' big ones.",
                     "By afternoon there are people reading. Court folk and House folk, side by side, not speaking.",
                     "Nobody wins this. But it can be read. That's something."] },
    } },

    "e3-penumbra": { who: { penumbra: "Penumbra" }, nodes: {
      a: { say: ["In the Ford's sewing workshop, an old woman embroiders with her eyes very close to the cloth. Her fingers are crooked, but the needle still moves fast.",
                 "They ask me for old ribbons. Law of Return ribbons, with their names embroidered, to prove at the Trial they were thrown out. People lost them, or burned them, or the mice ate them.",
                 "And I could embroider them again. Just the same. With the same grey thread. Nobody would tell the difference. Not even me."],
           opts: ["“If they're true, what does it matter that they're new?”", "“Embroider them. Those people were thrown out.”", "“No. A new ribbon is false evidence.”", "“Embroider new ribbons that say they're new.”"] },
      importa: { say: ["It matters because if one is found out, they all fall. The true ones too.",
                       "It happened to me with the false names, long ago. I embroidered one too many and the Court had to pay for all of them."] },
      bordar: { say: ["She embroiders all week. Two hundred ribbons. The true ones and the new ones, in the same basket.",
                      "At the Trial, a House judge pulls a thread from a ribbon and holds it to the light. It's too bright to be twenty years old.",
                      "I knew. I knew and I did it anyway. Now the true ones aren't worth anything either."] },
      no: { say: ["Then two hundred families testify with nothing in their hands. Against Houses that have papers for everything.",
                  "She goes back to the needle. She doesn't look at you. She used to sew faster."] },
      nuevas: { say: ["That say they're new?",
                      "She thinks it over. She threads a different thread, white.",
                      "She embroiders the ribbons with each family's name and, beside it, in white: “Embroidered again, in the era of the Lake, because the first was lost.” They prove nothing. But nobody can say they lie.",
                      "Memory can be mended too, if you let the mend show."] },
    } },

    "e3-albura": { who: { albura: "Judge Albura" }, nodes: {
      a: { say: ["At night, when the square empties, the judge stays sitting on the platform with her robe unbuttoned. There's a pile of empty cups at her feet. More than any witness drank.",
                 "I drink them all. Every piece of evidence they bring me, I drink it, to judge fairly. Three hundred now.",
                 "This morning my daughter came to fetch me and I didn't know her name. I knew the name of the daughter of a Court woman who died at the Night of Lanterns. Mine, I didn't."],
           opts: ["“Stop drinking. Judge by what they say.”", "“What's your daughter's name?”", "“Tell the Trial what the water took from you.”", "“Go on. It's the price of judging well.”"] },
      hija: { say: ["The judge opens her mouth. Closes it.",
                    "It starts with A. I think. Or N. She has her father's eyes. That I do know, because I saw it in the water: her father was holding her the night of the Night of Lanterns.",
                    "Her eyes fill with tears. She doesn't know who she's crying for."] },
      dejar: { say: ["Judge without drinking? Then I judge by what I'm told, and I'm told what suits them.",
                     "But she pushes the cups away with her foot.",
                     "Tomorrow I don't drink. Let's see what trial comes from a judge who only listens. Maybe it's worse. Maybe I'll remember my daughter's name."] },
      decir: { say: ["The next morning, before the first witness, the judge stands up.",
                     "I declare that I drank three hundred pieces of evidence and forgot my daughter's name. I declare that the water doesn't lie, but it charges. Let every people know what its evidence costs before bringing it.",
                     "That week the line of witnesses shrinks by half. The Tides sell less water. Ola says nothing, but counts the barrels with a frown."] },
      seguir: { say: ["The price of judging well. Yes. I tell myself that every night.",
                      "She buttons her robe. She drinks another cup, slowly, looking at the empty square."] },
    } },

    "e3-plaza": { who: { candela: "Candela Albor", umbela: "Umbela, Court archivist" }, nodes: {
      a: { say: ["A few weeks after your testimony, the Square of the Trial wakes with its platforms smashed. Someone pulled them down in the night.",
                 "In the middle, Candela and a veiled woman are shouting at each other. They fall silent when they see you.",
                 "Here comes the one who testified. Let them tell us what we do now with what they said."],
           opts: ["“What happened to the Court since I blamed it?”", "“What happened to the Houses since I blamed them?”", "“I said they all drank. What happened?”", "Help put the platforms back up", "Leave"] },
      corte: { say: ["Nobody sells bread to anyone in a veil. Court children don't get into the Meadow school. They gave us a deadline to pay what we don't have.",
                     "And you lot smashed the platforms. That doesn't fix anything.",
                     "No. But it gets heard. Your testimony got heard too, Caretaker. Loudly."] },
      casas: { say: ["My father sold the Tower of Dawn to pay. Now the Tower belongs to the Guild. They light furnaces where the lanterns used to be.",
                     "And the Court celebrated for a week. Now they look at us the way we used to look at them. It isn't better.",
                     "Don't say that. Tell me it was worth it. At least you tell me."] },
      nadie: { say: ["Nobody paid. And since nobody paid, everyone collects on their own. Last night someone from the Houses burned a Court family's door. Tonight someone from the Court smashed the platforms.",
                     "You said we all drank. You were right. And being right didn't stop anything.",
                     "The two of them stand looking at you. For once they agree on something."] },
      levantar: { say: ["You lift a platform. Candela comes over and holds the other side. After a while, Umbela helps too, without speaking.",
                        "When it's done, the two go off by different streets. But the platform stands, and that afternoon the Trial goes on."] },
      irse: { say: ["You leave. Behind you, the shouting starts again. Something of what you said on the platform is in each of them."] },
    } },
  });

  add("crater", {
    "e3-tizon": { who: { tizon: "Master Tizón" }, nodes: {
      a: { say: ["In a little forge at the edge of the Crater, an old man is hammering a horseshoe. Just that: a horseshoe. His back is bent and his arms still strong.",
                 "The cups disgust me. Thirty years making iron so my apprentice ends up blowing little glasses of memories.",
                 "But the Fire has never eaten so well. My grandchildren have shoes. I think about that too, when it disgusts me."],
           opts: ["“What would you have done?”", "“Talk to Fogarín. He listens to you.”", "“Teach the apprentices to make something else.”", "“Shoes matter too.”"] },
      usted: { say: ["The same. Sell. The Fire always sold what it was asked for. I sold long tubes to House Alba knowing what they were for.",
                     "The difference is I didn't ask myself questions. Fogarín asks himself all of them, and sells anyway. I don't know which is worse."] },
      fogarin: { say: ["Listens to me? He listens to me about everything except what matters.",
                       "But he goes down to the big workshop the next day. You hear him from the door: he doesn't shout. He speaks softly, as to an apprentice.",
                       "That afternoon, the cup furnace goes out an hour early. It isn't much. But it had never gone out early."] },
      aprendices: { say: ["Something else? Horseshoes? Nobody pays for a horseshoe what they pay for a cup.",
                          "But the next day there are three apprentices in the little forge. They're learning to make nails. They laugh at how boring it is.",
                          "Some day someone will need a nail and not a cup. That day, let there be someone who knows how."] },
      zapatos: { say: ["They matter. That's the problem. If they didn't, it would be easy.",
                       "He goes back to the horseshoe. He finishes it, plunges it into the water and watches it steam."] },
    } },

    "e3-lacre": { who: { lacre: "Lacre, sealer", fogarin: "Fogarín" }, nodes: {
      a: { say: ["In a Crater cellar, a man with nails stained with red wax is sealing cups at top speed. The cups don't come from the lake. They come from a barrel of river water, tinted with soot.",
                 "Don't look at me like that. I put on the Guild's seal. What's inside, let the buyer judge.",
                 "Besides, look: people drink this and see what they want to see. Same as with the real ones. What's the difference?"],
           opts: ["“The difference is the real ones cost the Root memory.”", "Report him to the Guild", "Try one of his cups", "Let him work"] },
      raiz: { say: ["Then mine are better. They don't take anything from anyone.",
                    "He laughs. Then he stops laughing, because he's thinking about it seriously.",
                    "All right. They don't take anything from the Root. They take the truth from whoever drinks. I suppose that's something."] },
      gremio: { say: ["Fogarín comes down to the cellar with two guards. Lacre doesn't run. He hands over the seal without protest.",
                      "I knew there were fakes. I didn't know how many. How many, Lacre?",
                      "Half the ones testified with at the Trial this month.",
                      "Fogarín sits down on a barrel. He says nothing for a long while."] },
      probar: { say: ["You drink one of Lacre's cups. It tastes of river and soot. You see nothing. Then, because you expect to see something, you see a square with lanterns.",
                      "It isn't a vision. It's your own memory of the Night of Lanterns, filling the gap.",
                      "See? Everyone brings their own vision. I only sell the cup."] },
      dejar: { say: ["You climb the stairs. Behind you, the seal comes down again and again on the wax, with a dry thud, like a heart."] },
    } },

    "e3-junco": { who: { junco: "Junco, cooler" }, nodes: {
      a: { say: ["At the cold-water dam where the cups are tempered, an older woman is pulling a worker out of the water. The man is crying and calling for a mother who isn't his.",
                 "Cup fever. The ones who temper the glass with lake water end up with their heads full of other people. This one thinks he's the son of a Tides fisherwoman.",
                 "Fourteen this moon. I give them cold dam water and it eases a little. Never completely."],
           opts: ["“Does the Guild know?”", "Help her with the worker", "“Temper the cups with dam water, not lake water.”", "Take the sick to the Wood, to the forgetting ceremony"] },
      gremio: { say: ["It knows. It pays the dam workers a bit more. They call it the forgetting wage.",
                      "I don't get the fever because I don't touch the glass. I only pull them out of the water. But at night I dream of faces I don't know. I suppose that's catching too."] },
      ayudar: { say: ["The two of you pull him out. You wrap him in a blanket. You give him your water bottle.",
                      "The man drinks and looks at you. For a moment his eyes are his own again.",
                      "“Where's my daughter?” he asks. Junco tells him his daughter's name. He nods. After a while he starts calling for the fisherwoman again."] },
      presa: { say: ["With dam water the glass can't hold the memory. It cracks within a week. They've tried it.",
                     "But it cracks. It doesn't sell. And the workers don't get sick.",
                     "She puts it to the Guild. Fogarín agrees for half the furnaces. The other half carries on. In the new half, nobody cries at the dam."] },
      bosque: { say: ["You take four workers to the Wood. Llovizna meets them with her spoon hanging from her neck and sings them the song that forgets.",
                      "By dawn, all four know their own names. But they don't remember the name of the village they were born in either. Forgetting doesn't choose what it takes.",
                      "Better with no village than with someone else's mother. I think. I don't know."] },
    } },

    "e3-ascuas": { who: { fogarin: "Fogarín" }, nodes: {
      a: { say: ["It's the Night of Embers. Once a year the whole Crater used to put out its furnaces so the ground could cool. This year the Guild said no: too many orders from the Trial.",
                 "I invented this night, you know? Well, I didn't invent it. I proposed it. One night for the ground to rest. And now I'm the master who cancels it.",
                 "Behind him, the furnaces roar. The Crater floor is so hot you can feel it through your boots."],
           opts: ["“Put out yours, at least.”", "Convince the workers to put out the furnaces", "“Put them all out. Let the Trial wait.”", "“There'll be another night.”"] },
      suyo: { say: ["Fogarín puts out his furnace. Only his. The big workshop goes quiet in one corner, while the others carry on.",
                    "One furnace. One furnace cools nothing. But let it be seen that the master put out his."] },
      obreros: { say: ["You go from workshop to workshop. Some listen. Others don't. An old glassblower puts hers out first. Then Ampolla. Then ten more.",
                       "By midnight, half the Crater is dark. The ground begins to cool, slowly, like someone sighing.",
                       "Half. Without the Guild ordering it. If the Fire has to go to the Heart, I'll go with this half, not the other."] },
      todos: { say: ["All of them? The Guild will remove me tomorrow.",
                     "He does it anyway. He goes round the Crater putting out furnaces with a bucket of sand. Nobody stops him. The master gives the orders.",
                     "The next day, the Guild suspends him for a week. The Trial's cups arrive late. The Crater floor is warm, not hot, for the first time in years."] },
      otra: { say: ["There'll always be another night. That's what everyone always says."] },
    } },

    "e3-fragua": { who: { fragua: "Master Fragua" }, nodes: {
      a: { say: ["In the Guild's Council hall, a burly man in a new leather apron has a map of the Meadow spread on the table. There are red crosses on every House forge.",
                 "If the Trial blames the Houses, they'll have to sell. If we buy now, before the verdict, we buy at half price. It's arithmetic.",
                 "Fogarín doesn't want to. Fogarín is a dreamer. The Guild needs someone who can count."],
           opts: ["“And if the Trial blames the Court?”", "“Buying before the verdict is betting against a people.”", "Warn the Houses", "“Buy. The Houses bought cheap when it suited them.”"] },
      corte: { say: ["Then the Houses don't sell and we lose the deposit. That's why we buy little: three forges. The oldest ones.",
                     "But the Court won't lose. Nobody believes the Court. That's arithmetic too."] },
      apostar: { say: ["Betting? It's trade. The Houses bought the Crater's coal at half price for a hundred years because they knew when we'd be hungry.",
                       "Now we know. Do you want the Fire to be the only people that doesn't learn?"] },
      advertir: { say: ["You tell Candela about the red crosses. She tells the Houses. The Houses refuse to sell a single forge until the verdict.",
                        "Fragua is waiting for you at the edge of the Meadow, arms crossed.",
                        "Well played. Now, if they're blamed, they'll sell dearer and to others. To the Heights' guild, say. Is that better for anyone?"] },
      comprar: { say: ["Fragua signs three purchases that same afternoon. The Houses sell because they're afraid. Nobody knows the verdict yet.",
                       "Three forges. Tomorrow, if the Trial goes as it should, thirty. The Fire will rule the Glade, Caretaker. For the first time."] },
    } },

    "e3-guijo": { who: { guijo: "Guijo" }, nodes: {
      a: { say: ["At the mouth of the south tunnel, a miner of about thirty with a hammer at his belt is reading the label on a cup someone left on the ground: “Tunnel nine. The Calm. Boy with a hammer.”",
                 "That's me. The boy with the hammer. They sent me down tunnel nine at twelve, and someone drank what the Root felt while I was picking.",
                 "They sell it in the Meadow. People who don't know me know what my hands were like that day. I don't remember. They do."],
           opts: ["“Do you want to see it?”", "Buy all the tunnel-nine cups", "“You testify. You were there.”", "Break the cup"] },
      ver: { say: ["See myself at twelve, from the stone? No.",
                   "Well, yes. A bit. But not today. Today I want to remember I got out. That's in no cup. The Root didn't feel it when I got out."] },
      comprar: { say: ["You buy what you can find at the market: eleven cups with the same label. You give them to Guijo.",
                       "He takes them to the mouth of tunnel nine, which is blocked with stones. He buries them there, one by one, without opening them.",
                       "Let the Root have them back. They were its before they were mine."] },
      declarar: { say: ["At the Trial? Say what? That they sent me down? Everyone knows. Nobody knows who.",
                        "He goes anyway. He testifies that there was a forewoman who crossed out names. That once she moved him to another tunnel. That he doesn't know if that makes her guilty or not.",
                        "They asked whose side I was on. I said the side of the ones who got out. They laughed. Then they wrote it down."] },
      romper: { say: ["You smash the cup against the stone. The water trickles into the tunnel mouth.",
                      "Thanks. There are a hundred others. But not this one."] },
    } },

    "e3-reserva": { who: { fogarin: "Fogarín", ola: "Ola" }, nodes: {
      a: { say: ["In a hidden Crater storehouse, Fogarín and Ola stand in front of an empty shelf. Until yesterday there were hundreds of sealed cups: the reserve, what wasn't sold.",
                 "They took them. Last night. Someone from the Guild, or someone from the Tides, or both.",
                 "The reserve was for giving back. Now it's at the Trial, testifying for someone. Nobody steals memory to throw it in the lake."],
           opts: ["“Who knew where it was?”", "Follow the cart tracks", "“Start another reserve. Smaller, and let another people keep it.”", "“It was a good idea. Good ideas get stolen.”"] },
      quien: { say: ["Her, me, and the two apprentices who carried the crates. One's from the Tides. The other's my nephew.",
                     "Don't look at me. My apprentice can't even count to a hundred."] },
      rastro: { say: ["You follow the wheel tracks to the Meadow road. The tracks end at the back door of the Square of the Trial.",
                      "Inside, the judge's clerk signs a receipt: “Evidence received, no sender.” No cup carries the name of who brought it.",
                      "They offered them as evidence. To both sides, half each. Whoever stole them didn't want to win. They wanted the Trial never to end."] },
      otra: { say: ["Another people? Who? Nobody wants to keep what they can't sell.",
                    "They think it over. In the end they send the new reserve to the White Deep, to the Watch hall, where the dreamers don't drink.",
                    "The ones who lost most to the water are the ones who want it least. Let them keep it."] },
      idea: { say: ["Good ideas get stolen. Yes. Bad ones too, but nobody wants those.",
                    "Ola puts her hand on his shoulder. They stand a while looking at the empty shelf, like two old people looking at the sea."] },
    } },
  });

  add("forest", {
    "e3-yedra": { who: { yedra: "Yedra" }, nodes: {
      a: { say: ["In the same old hammock, hung between two oaks, an older woman sways with a little barrel between her legs. Lake water, in the Wood, in plain sight.",
                 "The Council forbade bringing it. It didn't forbid swaying with it. The Wood's bans always have holes. They were made by people who forget.",
                 "I sell it to the young ones. Cheaper than at the lake, so they don't have to go. If they stay here, at least they come home to sleep."],
           opts: ["“You're selling them what the Council forbids.”", "Buy the whole barrel to pour it away", "Tell the Council", "“Better here than at the lake. You're right.”"] },
      prohibe: { say: ["I sell them what they'll drink anyway. The Council forbids and goes to sleep. I stay up with them.",
                       "Twenty years ago I sold fruit. The fruit was poison too. Nobody said anything because it was sweet."] },
      comprar: { say: ["You pay for the barrel. Yedra empties it on the ground, slowly, without regret.",
                       "Tomorrow I'll bring another. But not today. Today the young ones will have to be bored. Being bored does you good."] },
      avisar: { say: ["Llovizna comes with two guards. They take the barrel. Yedra doesn't protest.",
                      "That night, four Wood youngsters go down to the lake instead of staying at the hammock. One doesn't come back until the third day.",
                      "See? The ban worked. Now they drink further away."] },
      razon: { say: ["Of course I'm right. Being right and being good are different things. I only have the first.",
                     "She sways. The barrel creaks between her legs like a cat."] },
    } },

    "e3-bruma": { who: { bruma: "Bruma" }, nodes: {
      a: { say: ["In a cabin at the edge of the Wood, an old Shadow man is peeling potatoes on his doorstep. He wears the Court's veil mended with leaves.",
                 "The Court asks me to go to the Trial. I'm the last one who came to the Wood fleeing the Law of Return and still remembers.",
                 "The Wood asks me not to go. It says what happened at the Hedge is the Wood's business. Both are right. I have potatoes."],
           opts: ["“What happened at the Hedge?”", "“Go. You're a living witness.”", "“Stay. The Wood gave you a home.”", "“Tell Cuarzo, so he carves it in stone.”"] },
      seto: { say: ["They let us in. That's what nobody says. The Wood shut the door on us afterwards, but first it let us in. Me and my children.",
                    "If I testify, the Court will say the Wood threw us out. And it's true. But it's also true it saved us. Which will they believe?"] },
      ir: { say: ["He goes. You go with him along the Meadow road, slowly, with his branch walking stick.",
                  "I testify that the Wood let me in and then wanted me out. I testify that the Court asked me to come and will then ask me to keep quiet about half.",
                  "Nobody applauds. But a Light judge writes it all down, slowly, without cutting."] },
      quedar: { say: ["It gave me a home. Yes. And these potatoes, and the veil mended with leaves.",
                      "He stays. The Court doesn't forgive him. A veiled messenger leaves a letter at the door: it says nothing, it only has the seal."] },
      cuarzo: { say: ["In stone? For ever? I liked things being forgotten. That's why I came to the Wood.",
                      "But he goes down to the Caves with you. Cuarzo carves what he tells, both halves, the open door and the closed door, on the same piece of wall.",
                      "There it is. Now nobody can cut it. Not the Court, not the Wood."] },
    } },

    "e3-orilla": { who: { retono: "Retoño", llovizna: "Llovizna" }, nodes: {
      a: { say: ["On the lakeshore, far from the Tides' line, three Wood youngsters sit with their feet in the water. Their skin is grey and their nails purple. They've been there for days.",
                 "They're the ones who didn't come back. The ones who came with me the first time. They don't remember the Wood any more. They remember the Night of Lanterns, the Law of Return, the Hondura. Everything they drank.",
                 "One of them looks at you and calls you by a name that isn't yours. It's the name of a Hondura miner, dead a generation ago."],
           opts: ["“What are their names?”", "Take them to the Wood", "Ask Llovizna to come and sing here", "Leave them"] },
      nombres: { say: ["Mora, Tallo and Abedul. Mora doesn't answer to her name any more. Tallo, sometimes. Abedul thinks he's a little girl from the Quarter.",
                       "I drank the same as them. I was saved because I came back sooner. I don't know why I came back. Maybe because the bottle was empty."] },
      llevar: { say: ["You lead them back, one by one, to the entrance of the Wood. They don't resist. They walk like sleepwalkers.",
                      "At the Wood's gate, Tallo's mother hugs him. He doesn't recognise her. But he lets himself be held, and after a while rests his head on her shoulder.",
                      "Something stays. Something that isn't memory. I don't know what it is. But it stays."] },
      llovizna: { say: ["Llovizna comes to the shore with her spoon hanging from her neck and three Council guards. She forces nothing. She sits with them and sings the song that forgets.",
                        "By dawn, all three are crying. They cry for things they never lived, and then they stop crying. They get up on their own.",
                        "The Wood doesn't know how to remember. It knows how to forget well. Today that was useful. If the Heart calls, we'll go with this song and with these three."] },
      dejar: { say: ["You leave them. It's all right. I left them once too.",
                     "He sits down with them. He puts his feet in the water. At least he isn't drinking."] },
    } },

    "e3-hojas": { who: { llovizna: "Llovizna" }, nodes: {
      a: { say: ["In Llovizna's house there's a wooden box full of dry leaves written on by hand. On top, a letter with the Heights' seal.",
                 "A merchant wants to buy them. Grandpa's leaves. Everything he was forgetting that I wrote down for him. He says they're dry visions: memories without water, that take nothing from anyone.",
                 "He pays more than the Council earns in a year. And he's right: they take nothing from the Root. They only take them from me."],
           opts: ["Read some of the leaves", "“Don't sell them.”", "“Sell them. The Wood needs that money.”", "“Copy them for anyone who wants, for free.”"] },
      leer: { say: ["You read at random. “I came to the Wood with an acorn. They let me in. I closed the Hedge behind me.” “The old lullaby had one more verse. I don't remember which.” “Llovizna sings badly. Don't tell her.”",
                    "I wrote that last one, because he dictated it laughing. It was the last time he laughed."] },
      no: { say: ["I won't sell them. I knew already. I needed someone to say it out loud.",
                  "She keeps the box under the bed. The Heights letter she uses to light the fire."] },
      vender: { say: ["Llovizna sells the box. The Council fixes the roof of the meeting house and buys blankets for the winter.",
                      "A month later, at the Trial, someone from the Houses testifies with one of Grandpa's leaves: “I closed the Hedge behind me.” They say it proves the Wood threw people out too.",
                      "It was a leaf of my grandfather's. Now it's evidence. He wouldn't have understood. Neither do I."] },
      copiar: { say: ["Copy them? All of them? There are four hundred.",
                      "The Wood's young ones copy them for a whole moon, on new leaves. The originals stay in the box. The copies are handed out in the Wood's square.",
                      "Now nobody can sell them, because everyone has them. Grandpa belongs to everyone. He'd have been embarrassed. And he'd have liked it."] },
    } },

    "e3-seto": { who: { abrojo: "Abrojo, Hedge guard" }, nodes: {
      a: { say: ["At the Hedge, an old man with a bent back is pruning branches with enormous shears. The thorns are green. The Hedge is growing again.",
                 "The Council wants to close the Hedge again. Not to keep people out: to keep them in. So the young don't go off to the lake.",
                 "A generation ago I closed the Hedge so the displaced couldn't come in. Now they ask me to close it so our children can't leave. It's the same Hedge. The same shears."],
           opts: ["“What do you think?”", "“Close it. The young are getting lost.”", "“Leave it open. A closed wood doesn't protect, it imprisons.”", "“Open it only by day.”"] },
      cree: { say: ["I think a closed Hedge lasts as long as it takes someone to jump it. The young jump.",
                    "And I think an old man who closed a door once wants to close it again to feel the first time wasn't a mistake."] },
      cerrar: { say: ["Abrojo closes the Hedge. The branches weave themselves together, fast, as if they'd been waiting.",
                      "That night two youngsters hurt themselves jumping it. One reaches the lake with his legs full of thorns. He drinks more than ever.",
                      "Again. The same shears."] },
      abrir: { say: ["Open. All right. Let the Council tell me I'm an old man who lost his fear.",
                     "He cuts the branches that were weaving together. He leaves a wide gap, with no gate. That night young people go out through it. Some come back the same way, by day, in plain sight."] },
      dia: { say: ["By day? Like a shop?",
                   "He thinks it over. He likes it. He opens the Hedge at dawn and closes it at dusk. The young go to the lake and come back before nightfall, because the gate closes.",
                   "Not all of them. But the ones who come back sleep in their own beds. That's something."] },
    } },

    "e3-silencio": { who: { llovizna: "Llovizna" }, nodes: {
      a: { say: ["In the deepest clearing of the Wood the Long Silence is held: a night when nobody speaks and the song that forgets is sung, so that what hurts can go.",
                 "This year more people came than ever. People from the Meadow, the Court, the Tides. People who drank too much and want to forget what they saw.",
                 "It used to be for us. Now everyone comes. Some bring coins. They want to pay to forget. I never charged for the song."],
           opts: ["“Don't charge. This isn't for sale.”", "“Charge. The Wood needs something in return.”", "Join the Long Silence", "“If everyone forgets, who remembers the Line?”"] },
      linea: { say: ["Nobody. I know. That's why I hesitate.",
                     "But look at those faces. A Court woman who watched her mother die a hundred times. A judge who doesn't know her daughter's name. Do I tell them to remember for the good of the Glade?"] },
      nocobrar: { say: ["I won't charge. But then more will come. And one day someone will charge for me, somewhere else, without singing it right.",
                        "She sings all night, for free. At dawn, half of those who came leave without remembering why they came. They sleep peacefully for the first time in months."] },
      cobrar: { say: ["Llovizna sets a wooden spoon at the entrance to the clearing. People leave coins. By the end of the night, the spoon is full.",
                      "There. The Wood sells forgetting. Grandpa would die all over again.",
                      "A Court woman, as she leaves, counts the coins she left and smiles. She seems to have learned something. Something you don't like."] },
      unirte: { say: ["You sit in the circle and close your eyes. The song comes in slowly. You feel something going: the taste of the lake water, the white square, the thirst below.",
                      "At dawn you wake calm. You know you forgot something. You don't know what. Your creature looks at you as if it recognised you again.",
                      "Don't worry. I didn't let you forget what matters. Only what wasn't yours."] },
    } },

    "e3-retono2": { who: { retono: "Retoño", llovizna: "Llovizna" }, nodes: {
      a: { say: ["In the Council house there's a new chair, smaller than the others. Retoño is sitting in it, his mouth no longer stained.",
                 "The Council offered him a place. To speak for the young. To tell us what they're looking for at the lake before they go.",
                 "And I don't know whether to accept. If I accept, I become one of those who forbid. If I don't, those who forbid go on knowing nothing."],
           opts: ["“Accept. You change more from inside.”", "“Don't accept. Stay with the young.”", "“Ask the Council to go down to the lake with you one night.”"] },
      aceptar: { say: ["Retoño sits in the small chair. Llovizna passes him the Council's spoon so he can speak.",
                       "First: that it's allowed to ask where we come from. Without punishment. The second I'll say later.",
                       "The elders look at each other. Nobody objects. Maybe because nobody remembers any more why it was forbidden."] },
      rechazar: { say: ["Yes. I'll stay with them. Someone has to be on the shore when they don't come back.",
                        "All right. But the chair stays empty. For when you want it.",
                        "The small chair stays in the hall, empty, for years. Nobody sits in it."] },
      bajar: { say: ["The Council, on the shore, at night, with the young?",
                     "They go down. Six Council elders and Retoño. They sit with the young on the shore. Nobody drinks. They talk until the sun comes up.",
                     "We didn't fix anything. But now they know why we go. And we know they're not made of stone."] },
    } },
  });
})(window.EVEVENTS_EN);
